questions.question:
The program gets exactly this input (two lines, each ending with a newline):

RP-01 An
RP-02 Bình

What does it print?

std::string id, name;
int records = 0;
while (!std::cin.eof()) {
    std::cin >> id;
    std::getline(std::cin, name);
    ++records;
}
std::println("{} [{}] [{}]", records, id, name);
